class TestBasicAnalysis:
    """Verify correct extraction of name, args, returns, branches, complexity."""

    def test_simple_function(self, analyzer: CodeAnalyzer):
        source = """
def greet(name: str) -> str:
    return f"Hello, {name}"
"""
        result = _analyze(source, analyzer)
        assert "greet" in result
        meta = result["greet"]
        assert meta.name == "greet"
        assert meta.args == ["name"]
        assert meta.returns == "str"
        assert meta.branches == 0
        assert meta.complexity == 1

    def test_function_with_multiple_args(self, analyzer: CodeAnalyzer):
        source = """
def add(a: int, b: int, c: int = 0) -> int:
    return a + b + c
"""
        result = _analyze(source, analyzer)
        meta = result["add"]
        assert meta.args == ["a", "b", "c"]
        assert meta.returns == "int"

    def test_function_no_return_type(self, analyzer: CodeAnalyzer):
        source = """
def do_something(x):
    print(x)
"""
        result = _analyze(source, analyzer)
        meta = result["do_something"]
        assert meta.returns == "Any"
        assert meta.args == ["x"]

    def test_function_no_args(self, analyzer: CodeAnalyzer):
        source = """
def constant() -> float:
    return 3.14
"""
        result = _analyze(source, analyzer)
        meta = result["constant"]
        assert meta.args == []
        assert meta.returns == "float"


# ---------------------------------------------------------------------------
# Branch & Complexity Counting
# ---------------------------------------------------------------------------

class TestBranchAndComplexity:
    """Verify branch counting and cyclomatic complexity calculation."""

    def test_if_statement(self, analyzer: CodeAnalyzer):
        source = """
def check(x: int) -> str:
    if x > 0:
        return "positive"
    return "non-positive"
"""
        result = _analyze(source, analyzer)
        meta = result["check"]
        assert meta.branches == 1
        assert meta.complexity == 2

    def test_if_else(self, analyzer: CodeAnalyzer):
        source = """
def classify(x: int) -> str:
    if x > 0:
        return "positive"
    elif x == 0:
        return "zero"
    else:
        return "negative"
"""
        result = _analyze(source, analyzer)
        meta = result["classify"]
        assert meta.branches == 2  # if + elif (else is not a separate branch node)
        assert meta.complexity == 3

    def test_while_loop(self, analyzer: CodeAnalyzer):
        source = """
def countdown(n: int) -> None:
    while n > 0:
        n -= 1
"""
        result = _analyze(source, analyzer)
        meta = result["countdown"]
        assert meta.branches == 1
        assert meta.complexity == 2

    def test_for_loop(self, analyzer: CodeAnalyzer):
        source = """
def sum_list(items: list) -> int:
    total = 0
    for item in items:
        total += item
    return total
"""
        result = _analyze(source, analyzer)
        meta = result["sum_list"]
        assert meta.branches == 1
        assert meta.complexity == 2

    def test_except_handler(self, analyzer: CodeAnalyzer):
        source = """
def safe_divide(a: float, b: float) -> float:
    try:
        return a / b
    except ZeroDivisionError:
        return float('inf')
"""
        result = _analyze(source, analyzer)
        meta = result["safe_divide"]
        assert meta.branches == 1  # except handler counts as branch
        assert meta.complexity == 2

    def test_nested_branches(self, analyzer: CodeAnalyzer):
        source = """
def complex_logic(x: int, y: int) -> str:
    if x > 0:
        if y > 0:
            return "both positive"
        else:
            return "x positive, y non-positive"
    else:
        return "x non-positive"
"""
        result = _analyze(source, analyzer)
        meta = result["complex_logic"]
        # if (outer) + if (inner) + else (inner) -> 3 branch nodes
        assert meta.branches == 3
        assert meta.complexity == 4

    def test_multiple_branch_types(self, analyzer: CodeAnalyzer):
        source = """
def multi_branch(a: int, items: list) -> int:
    total = 0
    if a > 0:
        for item in items:
            while item > 0:
                total += item
                item -= 1
    return total
"""
        result = _analyze(source, analyzer)
        meta = result["multi_branch"]
        assert meta.branches == 3  # if + for + while
        assert meta.complexity == 4


