class TestEdgeCases:
    """Test empty functions, decorators, async, lambda (not analyzed)."""

    def test_empty_function(self, analyzer: CodeAnalyzer):
        source = """
def empty() -> None:
    pass
"""
        result = _analyze(source, analyzer)
        meta = result["empty"]
        assert meta.branches == 0
        assert meta.complexity == 1

    def test_function_with_docstring_only(self, analyzer: CodeAnalyzer):
        source = """
def documented() -> str:
    \"\"\"Return a constant.\"\"\"
    return "hello"
"""
        result = _analyze(source, analyzer)
        meta = result["documented"]
        assert meta.branches == 0

    def test_decorated_function(self, analyzer: CodeAnalyzer):
        source = """
import functools

def decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@decorator
def target(x: int) -> int:
    return x * 2
"""
        result = _analyze(source, analyzer)
        # Both wrapper and target are FunctionDef nodes
        assert "wrapper" in result
        assert "target" in result
        assert result["target"].args == ["x"]

    def test_async_function(self, analyzer: CodeAnalyzer):
        source = """
async def fetch_data(url: str) -> dict:
    if url:
        return {"data": "mock"}
    return {}
"""
        result = _analyze(source, analyzer)
        assert "fetch_data" in result
        meta = result["fetch_data"]
        assert meta.args == ["url"]
        assert meta.branches == 1
        assert meta.complexity == 2

    def test_nested_functions(self, analyzer: CodeAnalyzer):
        source = """
def outer(x: int) -> int:
    def inner(y: int) -> int:
        return y + 1
    return inner(x)
"""
        result = _analyze(source, analyzer)
        assert "outer" in result
        assert "inner" in result
        assert result["outer"].args == ["x"]
        assert result["inner"].args == ["y"]

    def test_lambda_not_analyzed(self, analyzer: CodeAnalyzer):
        """Lambda expressions are not FunctionDef nodes, so they should be ignored."""
        source = """
add = lambda a, b: a + b
"""
        result = _analyze(source, analyzer)
        assert result == {}  # no FunctionDef found


