class TestErrorHandling:
    """Verify that CodeAnalyzer raises appropriate exceptions on invalid input."""

    def test_invalid_syntax_raises_syntax_error(self, analyzer: CodeAnalyzer):
        source = "def broken(: int): pass"
        with pytest.raises(SyntaxError):
            _analyze(source, analyzer)

    def test_empty_string_raises_syntax_error(self, analyzer: CodeAnalyzer):
        with pytest.raises(SyntaxError):
            _analyze("", analyzer)

    def test_non_python_code_raises_syntax_error(self, analyzer: CodeAnalyzer):
        source = "This is not Python code!!!"
        with pytest.raises(SyntaxError):
            _analyze(source, analyzer)

    def test_none_source_raises_type_error(self, analyzer: CodeAnalyzer):
        with pytest.raises(TypeError):
            _analyze(None, analyzer)  # type: ignore

    def test_non_string_source_raises_type_error(self, analyzer: CodeAnalyzer):
        with pytest.raises(TypeError):
            _analyze(123, analyzer)  # type: ignore


# ---------------------------------------------------------------------------
# Property-Based Tests (Structural Invariants)
# ---------------------------------------------------------------------------

class TestPropertyBased:
    """Verify invariants that should hold for any valid analysis."""

    def test_complexity_always_positive(self, analyzer: CodeAnalyzer):
        """Cyclomatic complexity should always be >= 1."""
        sources = [
            "def a(): pass",
            "def b(x):\n    if x: pass",
            "def c():\n    for i in []: pass",
            "def d():\n    while True: pass",
        ]
        for src in sources:
            result = _analyze(src, analyzer)
            for meta in result.values():
                assert meta.complexity >= 1, f"Complexity < 1 for {meta.name}"

    def test_branches_never_negative(self, analyzer: CodeAnalyzer):
        """Branch count should never be negative."""
        sources = [
            "def a(): pass",
            "def b(x):\n    if x: pass\n    else: pass",
        ]
        for src in sources:
            result = _analyze(src, analyzer)
            for meta in result.values():
                assert meta.branches >= 0

    def test_complexity_equals_branches_plus_one(self, analyzer: CodeAnalyzer):
        """Cyclomatic complexity = number of branch nodes + 1."""
        sources = [
            "def a(): pass",
            "def b(x):\n    if x: pass",
            "def c():\n    for i in []: pass\n    while True: pass",
        ]
        for src in sources:
            result = _analyze(src, analyzer)
            for meta in result.values():
                assert meta.complexity == meta.branches + 1, (
                    f"Complexity mismatch for {meta.name}: "
                    f"complexity={meta.complexity}, branches={meta.branches}"
                )

    def test_args_is_list_of_strings(self, analyzer: CodeAnalyzer):
        """Args should always be a list of strings."""
        source = "def f(a, b, c): pass"
        result = _analyze(source, analyzer)
        meta = result["f"]
        assert isinstance(meta.args, list)
        assert all(isinstance(arg, str) for arg in meta.args)

    def test_returns_is_string(self, analyzer: CodeAnalyzer):
        """Returns should always be a string."""
        source = "def f() -> int: pass"
        result = _analyze(source, analyzer)
        meta = result["f"]
        assert isinstance(meta.returns, str)


