class TestASTEdgeCases:
    """Test with unusual but valid AST structures."""

    def test_function_with_type_comments(self, analyzer: CodeAnalyzer):
        """Type comments (e.g., # type: (int) -> str) are not parsed by ast.unparse on returns."""
        source = """
def func(x):
    # type: (int) -> str
    return str(x)
"""
        result = _analyze(source, analyzer)
        meta = result["func"]
        assert meta.returns == "Any"  # no return annotation

    def test_function_with_star_args(self, analyzer: CodeAnalyzer):
        source = """
def variadic(*args, **kwargs) -> None:
    pass
"""
        result = _analyze(source, analyzer)
        meta = result["variadic"]
        assert "args" in meta.args
        assert "kwargs" in meta.args

    def test_function_with_default_mutable_arg(self, analyzer: CodeAnalyzer):
        source = """
def append_to(item, target=[]) -> list:
    target.append(item)
    return target
"""
        result = _analyze(source, analyzer)
        meta = result["append_to"]
        assert meta.args == ["item", "target"]

    def test_class_method(self, analyzer: CodeAnalyzer):
        """Methods inside a class are still FunctionDef nodes."""
        source = """
class Calculator:
    def add(self, a: int, b: int) -> int:
        return a + b
"""
        result = _analyze(source, analyzer)
        assert "add" in result
        meta = result["add"]
        assert meta.args == ["self", "a", "b"]
        assert meta.returns == "int"


