class TestRegression:
    """Ensure previously fixed bugs do not reappear."""

    def test_no_functions_in_module(self, analyzer: CodeAnalyzer):
        """Module-level code without functions should return empty dict."""
        source = """
import os
import sys

x = 42
print(x)
"""
        result = _analyze(source, analyzer)
        assert result == {}

    def test_function_with_only_pass_and_comment(self, analyzer: CodeAnalyzer):
        source = """
def noop() -> None:
    # just a comment
    pass
"""
        result = _analyze(source, analyzer)
        meta = result["noop"]
        assert meta.branches == 0
        assert meta.complexity == 1

    def test_unicode_in_source(self, analyzer: CodeAnalyzer):
        source = """
def greet(name: str) -> str:
    return f"Hello, {name} 👋"
"""
        result = _analyze(source, analyzer)
        assert "greet" in result
        assert result["greet"].args == ["name"]

    def test_very_large_function(self, analyzer: CodeAnalyzer):
        """Stress test with many branches."""
        lines = ["def large(n: int) -> int:"]
        for i in range(100):
            lines.append(f"    if n == {i}: return {i}")
        lines.append("    return -1")
        source = "\n".join(lines)
        result = _analyze(source, analyzer)
        meta = result["large"]
        assert meta.branches == 100
        assert meta.complexity == 101


